357|function resolveRequestedPathForIpc(filePath, options: { purpose?: string; baseDir?: fs.PathOrFileDescriptor } = {}) {
358|  const purpose = String(options.purpose || 'File read')
359|  let raw = rejectUnsafePathSyntax(filePath, purpose)
360|
361|  // Gateway-reported cwds (config `terminal.cwd`, remote sessions) routinely
362|  // arrive as `~/...`. Node's fs has no shell — without expansion the path
363|  // resolves under process.cwd() and every read "ENOENT"s forever.
364|  if (raw === '~' || raw.startsWith('~/') || raw.startsWith('~\\')) {
365|    raw = path.join(os.homedir(), raw.slice(1))
366|  }
367|
368|  if (/^file:/i.test(raw)) {
369|    let resolvedPath
370|
371|    try {
372|      const parsed = new URL(raw)
373|
374|      if (parsed.protocol !== 'file:') {
375|        throw new Error('not a file URL')
376|      }
377|
378|      resolvedPath = fileURLToPath(parsed)
379|    } catch {
380|      throw ipcPathError('invalid-path', `${purpose} failed: file URL is invalid.`)
381|    }
382|
383|    rejectUnsafePathSyntax(resolvedPath, purpose)
384|
385|    return path.resolve(resolvedPath)
386|  }
387|
388|  const baseInput = typeof options.baseDir === 'string' && options.baseDir.trim() ? options.baseDir : process.cwd()
389|  const safeBaseInput = rejectUnsafePathSyntax(baseInput, purpose)
390|  const resolvedBase = path.resolve(safeBaseInput)
391|  rejectUnsafePathSyntax(resolvedBase, purpose)
392|  const resolvedPath = path.resolve(resolvedBase, raw)
393|  rejectUnsafePathSyntax(resolvedPath, purpose)
394|
